{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.easyecom_db_returns_intermediate as WITH FlattenedItems AS ( SELECT r.order_id, r.INVOICE_ID, r.REFERENCE_CODE, r.CREDIT_NOTE_ID, r.credit_note_number, r.ORDER_DATE::TIMESTAMP AS ORDER_DATE, r.INVOICE_DATE::TIMESTAMP AS INVOICE_DATE, r.RETURN_DATE::TIMESTAMP AS RETURN_DATE, r.MANIFEST_DATE::TIMESTAMP AS MANIFEST_DATE, r.IMPORT_DATE::TIMESTAMP AS IMPORT_DATE, r.LAST_UPDATE_DATE::TIMESTAMP AS LAST_UPDATE_DATE, r.MARKETPLACE, r.MARKETPLACE_ID, r.REPLACEMENT_ORDER, TRIM(ri.value:suborder_id::STRING, \'\"\') AS SUBORDER_ID, TRIM(ri.value:suborder_num::STRING, \'\"\') AS SALEORDERITEMCODE, TRIM(ri.value:company_product_id::STRING, \'\"\') AS COMPANY_PRODUCT_ID, TRIM(ri.value:productName::STRING, \'\"\') AS PRODUCTNAME, TRIM(ri.value:product_Id::STRING, \'\"\') AS PRODUCT_ID, TRIM(ri.value:sku::STRING, \'\"\') AS SKU, TRIM(ri.value:return_reason::STRING, \'\"\') AS RETURN_REASON, TRIM(ri.value:inventory_status::STRING, \'\"\') AS INVENTORY_STATUS, ri.value:returned_item_quantity::FLOAT AS RETURNED_QUANTITY, ri.value:credit_note_total_item_excluding_tax::FLOAT AS TOTAL_RETURN_AMOUNT_EXCL_TAX, ri.value:credit_note_total_item_tax::FLOAT AS RETURN_TAX, ri.value:credit_note_total_item_shipping_charge::FLOAT AS RETURN_SHIPPING_CHARGE, ri.value:credit_note_total_item_miscellaneous::FLOAT AS RETURN_MISC FROM maplemonk.easyecom_easyecom_emma_returns AS r, LATERAL FLATTEN(input => r.ITEMS) AS ri ) SELECT fi.*, COALESCE(fi.TOTAL_RETURN_AMOUNT_EXCL_TAX, 0) + COALESCE(fi.RETURN_TAX, 0) + COALESCE(fi.RETURN_SHIPPING_CHARGE, 0) + COALESCE(fi.RETURN_MISC, 0) AS TOTAL_RETURN_AMOUNT FROM FlattenedItems fi QUALIFY ROW_NUMBER() OVER ( PARTITION BY fi.REFERENCE_CODE,fi.saleorderitemcode ORDER BY fi.LAST_UPDATE_DATE DESC ) = 1; create or replace table emmasleep_db.maplemonk.emmasleep_db_returns_consolidated as SELECT replace(e.reference_code,\'#\',\'\') reference_code, e.SALEORDERITEMCODE, e.ORDER_ID, UPPER(e.order_status) AS order_status, CAST(e.ORDER_DATE AS TIMESTAMP_NTZ) AS Order_Date, CAST(DELIVERED_DATE AS TIMESTAMP_NTZ) AS Delivered_Date, UPPER(e.marketplace) AS marketplace, UPPER(e.marketplace) AS MARKETING_CHANNEL, UPPER(e.marketplace) AS SOURCE, UPPER(e.PRODUCT_NAME) AS PRODUCT_NAME, e.SKU, UPPER(e.product_category) AS product_category, UPPER(e.product_sub_category) AS product_sub_category, e.quantity AS order_quantity, UPPER(e.CITY) AS City, UPPER(e.STATE) AS State, e.pincode, UPPER(e.COURIER) AS Shipping_Courier, e.awb, e.name AS NAME, e.email AS EMAIL, CAST(NULL AS VARCHAR) AS return_request_number, CAST(NULL AS TIMESTAMP_NTZ) AS original_return_request_date, CAST(NULL AS NUMBER(38,0)) AS no_of_return_requests_initiated, CAST(NULL AS ARRAY) AS list_of_pickup_couriers_assigned, CAST(NULL AS TIMESTAMP_NTZ) AS return_approved_date, CAST(NULL AS TIMESTAMP_NTZ) AS return_refunded_at, CAST(NULL AS TIMESTAMP_NTZ) AS return_inspected_date, CAST(r.return_date AS TIMESTAMP_NTZ) AS return_date, CASE WHEN COALESCE(IFF(return_date IS NOT NULL, 1, NULL), e.return_flag) = 1 THEN \'Approved\' ELSE NULL END AS return_approval_status, CASE WHEN COALESCE(IFF(return_date IS NOT NULL, 1, NULL), e.return_flag) = 1 THEN \'return\' ELSE NULL END AS return_request_type, CASE WHEN LOWER(r.return_reason) LIKE \'%lost%\' THEN \'lost\' WHEN LOWER(r.return_reason) LIKE \'%exchange%\' THEN \'exchange\' WHEN (LOWER(r.return_reason) LIKE \'%rto%\' OR LOWER(r.return_reason) LIKE \'%not serviceable%\') THEN \'RTO\' WHEN r.return_reason IS NOT NULL THEN \'return\' ELSE NULL END AS return_type, COALESCE(IFF(return_date IS NOT NULL, 1, NULL), e.return_flag) AS return_flag, r.RETURNED_QUANTITY AS TOTAL_RETURNED_QUANTITY, r.return_reason, e.Payment_mode, e.selling_price, r.PRODUCTNAME AS returned_product_name, cast(null as string) AS returned_product_variant, r.SKU AS returned_sku, r.TOTAL_RETURN_AMOUNT, CASE WHEN e.return_flag = 1 THEN e.tax ELSE 0 END AS TOTAL_RETURN_TAX, r.TOTAL_RETURN_AMOUNT_EXCL_TAX AS TOTAL_RETURN_AMOUNT_EXCL_TAX, r.saleorderitemcode AS returned_item_saleorderitemcode, CASE WHEN LOWER(r.return_reason) LIKE \'%exchange%\' THEN r.PRODUCTNAME END AS exchange_product_name, CASE WHEN LOWER(r.return_reason) LIKE \'%exchange%\' THEN cast(null as string) END AS exchange_product_variant, CASE WHEN LOWER(r.return_reason) LIKE \'%exchange%\' THEN r.sku END AS exchange_sku, CASE WHEN LOWER(r.return_reason) LIKE \'%exchange%\' THEN e.selling_price END AS exchange_product_total_price, CAST(NULL AS VARCHAR) AS exchange_status, e.order_status AS oms_order_status FROM (select * from emmasleep_db.maplemonk.emmasleep_db_sales_consolidated qualify row_number() over (partition by reference_code,saleorderitemcode order by shipping_last_update_date desc) = 1 )e LEFT JOIN maplemonk.easyecom_db_returns_intermediate r ON replace(e.reference_code,\'#\',\'\') = r.reference_code AND e.saleorderitemcode = r.saleorderitemcode; CREATE OR REPLACE TABLE maplemonk.emmasleep_db_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(\'MONTH\', order_date) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1) THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1) then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1) then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(selling_price) as total_sales FROM maplemonk.emmasleep_db_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_sales FROM maplemonk.emmasleep_db_returns_consolidated WHERE return_flag = 1 GROUP BY return_month,return_date,marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace order by order_date desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EMMASLEEP_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            